# T4 Tahap 1 - IELTS Writing (T1 & T2 -> 10 tugas masing-masing) + Speaking (5 set per part). Talented-authored.
import json
B = '/home/claude/teg-tutorial/mocktest/banks/'
CK1 = ['Overview sentence summarising the main trends/stages', 'Key features selected and compared with accurate numbers', 'Logical paragraphs and linking words (while, whereas, by contrast)', 'Range of vocabulary for change (rose, declined, peaked) without repetition', 'At least 150 words, no personal opinion']
CK2 = ['Answers every part of the question with a clear position', 'Main ideas supported with explanations and examples', 'Introduction, 2-3 body paragraphs and a conclusion', 'Accurate grammar with a mix of complex sentences', 'At least 250 words, formal tone']
P1 = '<b>You should spend about 20 minutes on this task.</b><br>'
P1E = ' Summarise the information by selecting and reporting the main features, and make comparisons where relevant. Write at least 150 words.'
P2 = '<b>You should spend about 40 minutes on this task.</b><br>'
P2E = '<br>Give reasons for your answer and include any relevant examples from your own knowledge or experience. Write at least 250 words.'
M2 = 'Model structure: (1) Introduction - paraphrase the question and state your position. (2) Body 1 - first main reason + explanation + example. (3) Body 2 - second reason or the other view + example. (4) Conclusion - restate your opinion in different words. Ask a VSA/Talented consultant to mark your full essay against the four official criteria: Task Response, Coherence and Cohesion, Lexical Resource, Grammatical Range and Accuracy.'
def tbl(head, rows): return '<table class="data"><tr>' + ''.join(f'<th>{h}</th>' for h in head) + '</tr>' + ''.join('<tr>' + ''.join(f'<td>{c}</td>' for c in r) + '</tr>' for r in rows) + '</table>'
def T1(sid, title, desc, table, model):
    return {'id': sid, 'title': 'Task 1 · ' + title, 'questions': [{'type': 'essay', 'min_words': 150, 'prompt': P1 + desc + P1E, 'table': table, 'checklist': CK1, 'model': model}]}
def T2(sid, q):
    return {'id': sid, 'title': 'Task 2 · Essay', 'questions': [{'type': 'essay', 'min_words': 250, 'prompt': P2 + q + P2E, 'checklist': CK2, 'model': M2}]}

t1 = [
 T1('W1e', 'Commuting', 'The table shows how workers in one Australian city travelled to work in 2010 and 2025 (percentage of all trips).',
    tbl(['Mode', '2010', '2025'], [['Car', '68%', '54%'], ['Train', '14%', '19%'], ['Bus', '9%', '8%'], ['Bicycle', '2%', '7%'], ['Walking', '4%', '6%'], ['Work from home', '3%', '6%']]),
    'The table compares the ways workers in an Australian city commuted in 2010 and 2025.\n\nOverall, the car remained the most common mode, but its share fell considerably, while train travel, cycling and working from home all became more popular.\n\nIn 2010, more than two thirds of trips (68%) were made by car, compared with just over half (54%) in 2025. The train was the second most popular option and rose from 14% to 19%. Bus use, by contrast, was almost unchanged at around 8-9%.\n\nThe smaller categories show the most striking relative growth. Cycling more than tripled, from 2% to 7%, and the proportion of people working from home doubled to 6%. Walking also increased, from 4% to 6%.\n\n(about 165 words)'),
 T1('W1f', 'Coffee prices', 'The table shows the average price of a cup of coffee (in AUD) in four cities in 2015, 2020 and 2025.',
    tbl(['City', '2015', '2020', '2025'], [['Sydney', '3.80', '4.20', '5.10'], ['Melbourne', '3.60', '4.10', '5.00'], ['Brisbane', '3.50', '3.90', '4.60'], ['Perth', '3.70', '4.00', '4.50']]),
    'The table illustrates how the average cost of a cup of coffee changed in Sydney, Melbourne, Brisbane and Perth between 2015 and 2025.\n\nOverall, prices rose in all four cities, and the increase was faster in the second five-year period. Sydney was consistently the most expensive city.\n\nIn 2015 prices were similar, ranging from AUD 3.50 in Brisbane to AUD 3.80 in Sydney. By 2020 each city had seen a moderate rise of 30 to 50 cents.\n\nBetween 2020 and 2025 the growth accelerated. Sydney and Melbourne recorded the largest jumps, reaching AUD 5.10 and AUD 5.00 respectively. Brisbane climbed to AUD 4.60, whereas Perth showed the smallest increase and became the cheapest city at AUD 4.50.\n\n(about 160 words)'),
 T1('W1g', 'Recycling a plastic bottle', 'The table describes the stages in recycling plastic bottles.',
    tbl(['Stage', 'What happens'], [['1. Collection', 'Bottles are collected from homes and recycling bins'], ['2. Sorting', 'Bottles are sorted by type and colour at a recycling centre'], ['3. Washing', 'Labels and dirt are removed with hot water'], ['4. Shredding', 'Clean bottles are cut into small flakes'], ['5. Melting', 'Flakes are melted and formed into pellets'], ['6. Manufacturing', 'Pellets are used to make new products, e.g. clothing or new bottles']]),
    'The table outlines the process by which used plastic bottles are recycled into new products.\n\nOverall, there are six stages, beginning with the collection of used bottles and ending with the manufacture of new items.\n\nFirst, bottles are collected from households and public recycling bins and taken to a recycling centre, where they are sorted according to their type and colour. Next, they are washed in hot water so that labels and dirt are removed.\n\nOnce clean, the bottles are shredded into small flakes. These flakes are then melted and shaped into pellets. Finally, the pellets are sent to factories, where they are used to produce new goods such as clothing or fresh bottles, which completes the cycle.\n\n(about 150 words)'),
 T1('W1h', 'Museum visitors', 'The table shows the number of visitors (in thousands) to three museums in one city each quarter of 2025.',
    tbl(['Museum', 'Jan-Mar', 'Apr-Jun', 'Jul-Sep', 'Oct-Dec'], [['Science Museum', '120', '95', '140', '110'], ['Art Gallery', '80', '85', '70', '105'], ['History Museum', '60', '65', '60', '62']]),
    'The table compares quarterly visitor numbers at three museums in a city during 2025.\n\nOverall, the Science Museum attracted the most visitors in every quarter, while the History Museum had the lowest and most stable figures.\n\nThe Science Museum began the year with 120,000 visitors, fell to 95,000 in the second quarter and then peaked at 140,000 between July and September, before declining to 110,000.\n\nThe Art Gallery followed a different pattern. Its numbers rose slightly from 80,000 to 85,000, dipped to a low of 70,000 in the third quarter, but then jumped to 105,000 at the end of the year.\n\nVisitor numbers at the History Museum hardly changed, staying between 60,000 and 65,000 throughout the year.\n\n(about 160 words)'),
 T1('W1i', 'Water use', 'The table shows average daily water use per person (litres) for different purposes in two countries.',
    tbl(['Purpose', 'Country A', 'Country B'], [['Showering', '60', '35'], ['Toilet', '40', '25'], ['Laundry', '25', '15'], ['Cooking & drinking', '10', '8'], ['Garden', '45', '5'], ['Total', '180', '88']]),
    'The table compares how much water a person uses each day for six purposes in Country A and Country B.\n\nOverall, people in Country A use more than twice as much water as those in Country B, and the gap is largest for gardening.\n\nIn Country A, the total is 180 litres per person per day. Showering accounts for the largest share at 60 litres, followed by gardening (45 litres) and the toilet (40 litres). In Country B, showering is also the main use, but at only 35 litres.\n\nThe biggest difference is in garden use: 45 litres in Country A compared with just 5 litres in Country B. By contrast, water used for cooking and drinking is almost the same in both countries, at 10 and 8 litres respectively.\n\n(about 160 words)'),
 T1('W1j', 'Online shopping', 'The table shows the percentage of people in different age groups who shopped online at least once a month in 2018 and 2025.',
    tbl(['Age group', '2018', '2025'], [['18-24', '62%', '88%'], ['25-34', '70%', '91%'], ['35-49', '55%', '82%'], ['50-64', '35%', '67%'], ['65+', '15%', '48%']]),
    'The table shows the proportion of people in five age groups who shopped online at least monthly in 2018 and 2025.\n\nOverall, online shopping became more common in every age group, and the gap between younger and older people narrowed.\n\nIn 2018, people aged 25-34 were the most frequent online shoppers (70%), followed by 18-24 year olds (62%). Only 15% of those aged 65 and over shopped online each month.\n\nBy 2025, the figures for the three youngest groups had risen to between 82% and 91%. The most dramatic growth, however, was among older people: the figure for 50-64 year olds almost doubled to 67%, and the proportion of over-65s more than tripled to 48%.\n\n(about 150 words)'),
]
t2 = [
 T2('W2e', 'Some people believe that university education should be free for all students. Others think students should pay at least part of the cost. Discuss both views and give your own opinion.'),
 T2('W2f', 'In many cities, more and more people live alone. What are the reasons for this? Is it a positive or negative development?'),
 T2('W2g', 'Some people think that the best way to reduce traffic congestion is to make public transport free. To what extent do you agree or disagree?'),
 T2('W2h', 'Many young people today spend a lot of time on social media. What problems can this cause, and what solutions can you suggest?'),
 T2('W2i', 'Some people say that learning a foreign language at primary school is better than learning it at secondary school. Do the advantages of this outweigh the disadvantages?'),
 T2('W2j', 'Tourism brings money to many countries, but it can also damage the environment and local culture. Do you think the benefits of international tourism outweigh the problems?'),
]
CKS = ['Answers fully and extends with reasons/examples', 'Speaks fluently with few long pauses', 'Uses a range of vocabulary and some less common words', 'Uses mixed grammar (past, present perfect, conditionals)', 'Clear pronunciation and natural stress']
def SQ(p, prep=0, speak=30): return {'type': 'speak', 'prompt': p, 'prep': prep, 'speak': speak, 'checklist': CKS}
s1 = [{'id': 'S1e', 'title': 'Speaking Part 1', 'questions': [SQ('Do you like music? What kind of music do you listen to?'), SQ('When do you usually listen to music?'), SQ('Did you learn to play an instrument as a child?'), SQ('Has your taste in music changed over the years?')]}]
s2 = [{'id': 'S2e', 'title': 'Speaking Part 2 & 3', 'questions': [SQ('<b>Describe a book or film that made you think.</b><br>You should say: what it was; when you read or watched it; what it was about; and explain why it made you think.<br><small>You have 1 minute to prepare and should speak for 1-2 minutes.</small>', 60, 120), SQ('Part 3: Why do some people prefer films to books?', 0, 60), SQ('Part 3: Should schools encourage students to read more fiction?', 0, 60), SQ('Part 3: How will people read in the future?', 0, 60)]}]

if __name__ == '__main__':
    d = json.load(open(B + 'ielts.json', encoding='utf-8'))
    for si, slot, sets in ((2, 'T1', t1), (2, 'T2', t2), (3, 'S1', s1), (3, 'S2', s2)):
        sl = [x for x in d['sections'][si]['slots'] if x['id'] == slot][0]; have = {x['id'] for x in sl['sets']}
        sl['sets'] += [x for x in sets if x['id'] not in have]
    json.dump(d, open(B + 'ielts.json', 'w', encoding='utf-8'), ensure_ascii=False)
    print('ok')
